import java.util.*;import java.nio.charset.*;
class MountainBlockExportTest{public static void main(String[]args)throws Exception{for(int m:new int[]{12,17,18}){int expected=1000000+m-10;for(int y:new int[]{200,195,180,152})if(ExportBlocks.block(200,m,62,0,0,0,y,3)!=expected)throw new AssertionError("Mountain material lost on exposed face at "+y);if(ExportBlocks.block(200,m,62,0,0,0,151,3)!=3)throw new AssertionError("Missing deep stone");if(ExportBlocks.block(200,m,62,4,0,0,201,3)!=16)throw new AssertionError("Snow layer changed");}var w=new TerraForge.World(32,62,71);Arrays.fill(w.height,200);w.environment.material=new byte[1024];Arrays.fill(w.environment.material,(byte)18);String chunk=new String(TerraForge.chunk(w,0,0),StandardCharsets.ISO_8859_1);int layered=0;for(String rock:new String[]{"minecraft:granite","minecraft:andesite","minecraft:tuff","minecraft:diorite","minecraft:calcite","minecraft:deepslate"})if(chunk.contains(rock))layered++;if(!chunk.contains("minecraft:granite")||layered<3)throw new AssertionError("Exported mountain faces should show the surface rock plus mixed rock patches: "+layered);for(int y=140;y<200;y++){int v=ExportBlocks.block(200,18,62,0,0,0,y,3,5,7,71);if(v!=3&&v!=2&&(v<1000000||v>1000010))throw new AssertionError("Non-rock block in strata at "+y);}if(ExportBlocks.block(200,18,62,0,0,0,200,3,5,7,71)!=1000008)throw new AssertionError("Surface rock replaced by strata");if(ExportBlocks.block(200,18,62,0,0,0,120,3,5,7,71)!=3)throw new AssertionError("Deep substrate should stay stone");try(var assets=new MinecraftAssets(MinecraftAssets.locate())){for(int m:new int[]{3,12,17,18})if(assets.block(ExportBlocks.block(200,m,62,0,0,0,170)).faces().isEmpty())throw new AssertionError("Missing vanilla model");if(assets.missingTextures!=0)throw new AssertionError("Missing vanilla texture");}System.out.println("PASS: mountain surface rock kept, exposed faces show mixed rock patches through section export, snow layers unchanged; deep substrate remains stone; vanilla textures load");}}
